package tracing

import (
	"context"
	"fmt"
	"sync/atomic"

	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"
)

// StartSpan creates a childspan and attaches to the context. This function
// exists primarily to ease the transition to opentelemetry. There are two
// issues with StartSpan.
//
//  1. It encourages adhoc tracing. The majority of traces should be generated by
//     middleware wrapping servers and clients.
//  2. Packages that do need custom tracing, like the jobSystem, should use
//     otel.Trace("github.com/project/pkg/name") to create a subsystem scoped tracer.
func StartSpan(
	ctx context.Context, spanName string, options ...trace.SpanStartOption,
) (context.Context, trace.Span) {
	return getAdhocTracer().Start(ctx, spanName, options...)
}

// adhocTracer exists to ease the migration to OpenTelemetry. The main purpose
// of a Tracer instance is identifying the library or package that generated the
// trace. Subsystems generating traces should use otel.Tracer(packageName) to
// create a subsystem scoped tracer.
var adhocTracer = atomic.Value{}

// getAdhocTracer returns a global tracer for the process.
func getAdhocTracer() trace.Tracer {
	if tracer, ok := adhocTracer.Load().(trace.Tracer); ok && tracer != nil {
		return tracer
	}
	return trace.NewNoopTracerProvider().Tracer("noop")
}

func EndWithError(span trace.Span, err error) {
	if err != nil {
		span.SetStatus(codes.Error, fmt.Sprintf("%+v", err.Error()))
	} else {
		span.SetStatus(codes.Ok, "")
	}
	span.End() // nolint:deferspanend -- span wasn't created here
}
